<?php
require __DIR__.'/includes/bootstrap.php';
$from=filter_var($_GET['from']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$to=filter_var($_GET['to']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$date=(string)($_GET['date']??date('Y-m-d'));$dateValid=valid_journey_date($date);if(!$dateValid)$date=date('Y-m-d');
$stations=$pdo->query('SELECT station_id,station_name FROM stations WHERE is_active=1 ORDER BY station_order,station_name')->fetchAll();
$sql='SELECT sc.schedule_id,sc.departure_time,sc.arrival_time,sc.service_days,t.train_name,t.train_code,r.route_name,r.route_id,r.distance_km,o.station_name AS origin_name,d.station_name AS destination_name FROM schedules sc JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id WHERE sc.is_active=1 AND t.is_active=1 AND r.is_active=1 AND o.is_active=1 AND d.is_active=1 AND (sc.valid_from IS NULL OR sc.valid_from<=?) AND (sc.valid_until IS NULL OR sc.valid_until>=?)';$params=[$date,$date];if($from){$sql.=' AND r.origin_station_id=?';$params[]=$from;}if($to){$sql.=' AND r.destination_station_id=?';$params[]=$to;}$sql.=' ORDER BY sc.departure_time';$stmt=$pdo->prepare($sql);$stmt->execute($params);$schedules=$stmt->fetchAll();$weekday=(new DateTimeImmutable($date))->format('D');$schedules=array_values(array_filter($schedules,static function(array $row)use($weekday):bool{$days=array_map('strtolower',array_map('trim',explode(',',(string)$row['service_days'])));return in_array('daily',$days,true)||in_array(strtolower($weekday),$days,true);}));
$pageTitle='Train schedules';require __DIR__.'/includes/header.php';?>
<section class="content"><span class="eyebrow">CAMPUS SHUTTLE</span><h1>Schedules & availability</h1><p>Search active trains and schedules by station and journey date.</p><form class="search" method="get"><label>From<select name="from"><option value="">Any station</option><?php foreach($stations as $s):?><option value="<?=e($s['station_id'])?>" <?=$from===(int)$s['station_id']?'selected':''?>><?=e($s['station_name'])?></option><?php endforeach?></select></label><label>To<select name="to"><option value="">Any station</option><?php foreach($stations as $s):?><option value="<?=e($s['station_id'])?>" <?=$to===(int)$s['station_id']?'selected':''?>><?=e($s['station_name'])?></option><?php endforeach?></select></label><label>Journey date<input type="date" name="date" min="<?=e(date('Y-m-d'))?>" value="<?=e($date)?>" required></label><button class="button">Search trains</button></form>
<div class="list"><?php foreach($schedules as $row):$available='Sign in to see your allocation';if(current_user()){$u=current_user();$q=$pdo->prepare('SELECT COUNT(*) FROM seats s JOIN bogies b ON b.bogie_id=s.bogie_id JOIN trains t ON t.train_id=b.train_id WHERE t.train_id=(SELECT train_id FROM schedules WHERE schedule_id=?) AND b.category=? AND b.gender=? AND b.is_active=1 AND s.is_active=1 AND NOT EXISTS(SELECT 1 FROM bookings x WHERE x.schedule_id=? AND x.journey_date=? AND x.seat_id=s.seat_id AND x.status="Confirmed")');$q->execute([$row['schedule_id'],$u['category'],$u['gender'],$row['schedule_id'],$date]);$available=(int)$q->fetchColumn().' seats in your bogie';} ?><article><div><span class="tag"><?=e($row['train_code'])?> · <?=e($row['service_days'])?></span><h3><?=e($row['train_name'])?></h3><p><?=e($row['origin_name'])?> → <?=e($row['destination_name'])?></p><p><?=e(substr($row['departure_time'],0,5))?>–<?=e(substr($row['arrival_time'],0,5))?> · <?=e($available)?></p></div><?php if(current_user()):?><a class="button" href="<?=e(app_url('booking.php',['schedule'=>$row['schedule_id'],'date'=>$date]))?>">Book seat</a><?php else:?><a class="button" href="<?=e(app_url('login.php'))?>">Sign in to book</a><?php endif?></article><?php endforeach?><?php if(!$schedules):?><article>No active trains serve this route and date.</article><?php endif?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
